/// Output for a resolved model route.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "exp.service.zeroclaw.route.result@v1"))]
pub struct ResolveRouteOutput {
